services_entry_t *get_entry(const char *name) {
  services_entry_t *out;
  HASH_FIND_STR(services, name, out);
  return out;
}

void add_entry(int idx, char *name, int svcs_len, const struct service *svc) {
  static_services_entries[idx].name = name;
  static_services_entries[idx].svcs = svc;
  static_services_entries[idx].len_svcs = svcs_len;
  HASH_ADD_STR(services, name, &static_services_entries[idx]);
}

